#include "compositors/niri/niri_config_blur.h"

#include "compositors/niri/niri_config_files.h"
#include "compositors/niri/niri_runtime.h"
#include "config/config_types.h"

#include <algorithm>
#include <cctype>
#include <charconv>
#include <filesystem>
#include <format>
#include <optional>
#include <system_error>
