namespace compositors::niri {
  namespace {

    constexpr std::string_view kManagedHeader =
        "// Generated by Helix from Control Center → Theme → Chrome. Edits here are overwritten.\n"
        "// Requires niri 26.04 or newer. Refraction requires helix-niri.\n";

    constexpr std::string_view kChromeNamespace =
        "^helix-(bar-.+|notification|dock|panel|attached-panel|osd|idle-grace|screenshot-region|annotate|overview-launcher)$";

    constexpr std::string_view kDisabledKdl = R"(window-rule {
    background-effect {
        blur false
    }
}

layer-rule {
    match namespace="^helix-"
    background-effect {
        blur false
    }
}
)";

    struct Version {
      int year = 0;
      int month = 0;
    };

    [[nodiscard]] std::optional<int> parseInt(std::string_view text) {
      if (text.empty()) {
        return std::nullopt;
      }
      int value = 0;
      const auto result = std::from_chars(text.data(), text.data() + text.size(), value);
      if (result.ec != std::errc{} || result.ptr != text.data() + text.size()) {
        return std::nullopt;
      }
      return value;
    }

    [[nodiscard]] std::optional<Version> parseVersion(std::string_view version) {
      std::size_t i = 0;
      while (i < version.size() && (std::isdigit(static_cast<unsigned char>(version[i])) == 0)) {
        ++i;
      }
      if (i >= version.size()) {
        return std::nullopt;
      }
      const std::size_t yearStart = i;
      while (i < version.size() && (std::isdigit(static_cast<unsigned char>(version[i])) != 0)) {
        ++i;
      }
      const auto year = parseInt(version.substr(yearStart, i - yearStart));
      if (!year.has_value() || i >= version.size() || version[i] != '.') {
        return std::nullopt;
      }
      ++i;
      const std::size_t monthStart = i;
      while (i < version.size() && (std::isdigit(static_cast<unsigned char>(version[i])) != 0)) {
        ++i;
      }
      const auto month = parseInt(version.substr(monthStart, i - monthStart));
      if (!month.has_value()) {
        return std::nullopt;
      }
      return Version{.year = *year, .month = *month};
    }

    // An empty param list means the compositor predates parameter reporting; the
    // default key set is written. Otherwise only listed keys are emitted so a newer
    // shell never fails the config load on an older helix-niri.
    [[nodiscard]] bool acceptsLiquidGlassParam(const std::vector<std::string>& params, std::string_view name) {
      if (params.empty()) {
        return true;
      }
      return std::find(params.begin(), params.end(), name) != params.end();
    }

    [[nodiscard]] std::string liquidGlassChild(float strength, const std::vector<std::string>& params) {
      std::string block = "        liquid-glass {\n";
      if (acceptsLiquidGlassParam(params, "refraction-strength")) {
        block += std::format("            refraction-strength {:.2f}\n", std::clamp(strength, 0.0F, 1.0F));
      }
      block += "        }\n";
      return block;
    }

    [[nodiscard]] std::string backgroundEffectBlock(
        bool blur,
        bool xray,
        bool liquidGlass,
        float strength,
        const std::vector<std::string>& params,
        bool blurOff = false
    ) {
      std::string block = "    background-effect {\n";
      if (blur) {
        block += "        blur true\n";
      } else if (blurOff) {
        block += "        blur false\n";
      }
      block += std::format("        xray {}\n", xray ? "true" : "false");
      if (liquidGlass) {
        block += liquidGlassChild(strength, params);
      }
      block += "    }\n";
      return block;
    }

    [[nodiscard]] std::string blurParamsKdl(const BlurSettings& settings) {
      const int passes = std::clamp(settings.passes, 1, 8);
      const float offset = std::clamp(settings.offset, 0.5F, 8.0F);
      const float noise = std::clamp(settings.noise, 0.0F, 0.2F);
      return std::format(
          "blur {{\n    passes {}\n    offset {:.1f}\n    noise {:.2f}\n    saturation 1.0\n}}\n", passes, offset, noise
      );
    }

  } // namespace

  std::filesystem::path blurIncludePath() { return includePath(kBlurIncludeFileName); }

  bool versionSupportsBlur(std::string_view version) {
    const auto parsed = parseVersion(version);
    if (!parsed.has_value()) {
      return false;
    }
    return parsed->year > 26 || (parsed->year == 26 && parsed->month >= 4);
  }

  bool versionSupportsLiquidGlass(std::string_view version) {
    return version.find("helix") != std::string_view::npos && versionSupportsBlur(version);
  }

  bool detectLiquidGlass(const NiriRuntime* runtime) {
    if (runtime == nullptr) {
      return false;
    }
    if (const auto capability = runtime->helixLiquidGlassCapability()) {
      return *capability;
    }
    if (const auto version = runtime->compositorVersion()) {
      return versionSupportsLiquidGlass(*version);
    }
    return false;
  }

  std::vector<std::string> detectLiquidGlassParams(const NiriRuntime* runtime) {
    if (runtime == nullptr) {
      return {};
    }
    return runtime->helixLiquidGlassParams().value_or(std::vector<std::string>{});
  }

  bool blurIncludeExists(const std::filesystem::path& configFile) {
    const auto path = configFile.empty() ? blurIncludePath() : configFile.parent_path() / std::string(kBlurIncludeFileName);
    std::error_code ec;
    return std::filesystem::exists(path, ec) && !ec;
  }

  BlurSettings blurSettingsFromConfig(const Config& config, bool helixNiri, std::vector<std::string> liquidGlassParams) {
    const auto& niri = config.theme.niriLayout;
    const float glass = resolvedPanelGlass(config.shell.panel);
    return BlurSettings{
        .enabled = niri.blur,
        .passes = niri.blurPasses,
        .offset = niri.blurOffset,
        .noise = niri.blurNoise,
        .refraction = config.shell.panel.refraction,
        .helixNiri = helixNiri,
        .highContrast = config.accessibility.highContrast,
        .refractionStrength = glass,
        .liquidGlassParams = std::move(liquidGlassParams),
    };
  }

  std::string kdlForBlur(const BlurSettings& settings) {
    std::string body(kManagedHeader);
    const float strength = std::clamp(settings.refractionStrength, 0.0F, 1.0F);
    const bool helixGlass =
        settings.helixNiri && settings.refraction && !settings.highContrast && strength > 0.001F;
    const bool stockChromeBlur = !settings.helixNiri && settings.refraction && !settings.highContrast;
    const bool chromeBlur = settings.enabled || stockChromeBlur;
    const bool windowBlur = settings.enabled;

    if (!windowBlur && !helixGlass && !stockChromeBlur) {
      body += kDisabledKdl;
      return body;
    }

    body += "window-rule {\n";
    const auto& params = settings.liquidGlassParams;
    body += backgroundEffectBlock(windowBlur, false, false, strength, params);
    body += "}\n\n";

    // Shell chrome must sample what is actually underneath (windows, workspace), not the
    // wallpaper-only xray path. Greeter below keeps xray — it sits over the wallpaper at login.
    body += std::format("layer-rule {{\n    match namespace=\"{}\"\n", kChromeNamespace);
    body += backgroundEffectBlock(chromeBlur, false, helixGlass, strength, params, helixGlass && !chromeBlur);
    body += "}\n\n";

    body += "layer-rule {\n    match namespace=\"helix-window-switcher\"\n";
    body += backgroundEffectBlock(chromeBlur, false, helixGlass, strength, params, helixGlass && !chromeBlur);
    body += "}\n\n";

    if (helixGlass) {
      body += "window-rule {\n    match app-id=\"^dev\\\\.helix\\\\.Greeter$\"\n";
      body += backgroundEffectBlock(false, true, true, strength, params, true);
      body += "}\n\n";
    }

    if (windowBlur || chromeBlur) {
      body += blurParamsKdl(settings);
    }
    return body;
  }

  InstallResult persistBlurFromConfig(const Config& config, const NiriRuntime* runtime) {
    return saveNiriBlur(
        blurSettingsFromConfig(config, detectLiquidGlass(runtime), detectLiquidGlassParams(runtime))
    );
  }

  InstallResult saveNiriBlur(const BlurSettings& settings) { return saveNiriBlurInto(configPath(), settings); }

  InstallResult saveNiriBlurInto(const std::filesystem::path& configFile, const BlurSettings& settings) {
    InstallResult result;
    if (configFile.empty()) {
      result.error = "niri config path is unknown";
      return result;
    }
    std::error_code ec;
    if (!std::filesystem::exists(configFile, ec) || ec) {
      result.error = "niri config not found";
      return result;
    }
    const auto include = configFile.parent_path() / std::string(kBlurIncludeFileName);
    if (!writeFile(include, kdlForBlur(settings), result.error)) {
      return result;
    }
    if (!appendInclude(configFile, kBlurIncludeFileName, result.error)) {
      return result;
    }
    result.ok = true;
    result.added = 1;
    return result;
  }

} // namespace compositors::niri
